<?php
require_once 'config/app.php';require_roles(['admin','operator']);$pageTitle='Data Pegawai';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);$d=[trim($_POST['nip']),trim($_POST['nama']),trim($_POST['jabatan']),trim($_POST['bidang']),trim($_POST['no_hp']),trim($_POST['alamat'])];if($id){$d[]=$id;$sql="UPDATE pegawai SET nip=?,nama=?,jabatan=?,bidang=?,no_hp=?,alamat=? WHERE id=?";}else{$sql="INSERT INTO pegawai(nip,nama,jabatan,bidang,no_hp,alamat) VALUES(?,?,?,?,?,?)";}try{$pdo->prepare($sql)->execute($d);flash('Data pegawai disimpan.');}catch(PDOException $e){flash('Gagal menyimpan. NIP mungkin sudah terdaftar.','danger');}redirect('pegawai.php');}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$q=$pdo->prepare("SELECT COUNT(*) FROM peminjaman WHERE pegawai_id=?");$q->execute([$id]);if($q->fetchColumn())flash('Pegawai memiliki riwayat transaksi, tidak dapat dihapus.','warning');else{$pdo->prepare("DELETE FROM pegawai WHERE id=?")->execute([$id]);flash('Data dihapus.');}redirect('pegawai.php');}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM pegawai WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$rows=$pdo->query("SELECT * FROM pegawai ORDER BY nama")->fetchAll();require 'includes/header.php';?>
<div class="d-flex justify-content-between mb-3"><h3>Data Pegawai</h3></div><div class="card mb-4"><div class="card-header bg-white fw-bold"><?=$edit?'Edit':'Tambah'?> Pegawai</div><div class="card-body"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><?php foreach(['nip'=>'NIP','nama'=>'Nama Lengkap','jabatan'=>'Jabatan','bidang'=>'Bidang/Unit Kerja','no_hp'=>'Nomor HP','alamat'=>'Alamat'] as $k=>$v):?><div class="col-md-4"><label class="form-label"><?=$v?></label><input class="form-control" name="<?=$k?>" value="<?=e($edit[$k]??'')?>" <?=$k==='nama'?'required':''?>></div><?php endforeach;?><div class="col-12"><button class="btn btn-primary">Simpan</button> <a class="btn btn-light" href="pegawai.php">Reset</a></div></form></div></div>
<div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>NIP</th><th>Nama</th><th>Jabatan</th><th>Bidang</th><th>HP</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nip'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['jabatan'])?></td><td><?=e($r['bidang'])?></td><td><?=e($r['no_hp'])?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$r['id']?>">Edit</a> <a class="btn btn-sm btn-outline-danger" onclick="return confirm('Hapus data?')" href="?delete=<?=$r['id']?>">Hapus</a></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'includes/footer.php';?>